        ["ZIP beklenmeyen bir klasör içeriyor."]="The ZIP contains an unexpected directory.",
        ["ZIP dosya yolu geçersiz."]="The ZIP file path is invalid.",
        ["ZIP paket klasörleri karışık."]="The ZIP package directory layout is inconsistent.",
        ["ZIP birden fazla paket klasörü içeriyor."]="The ZIP contains more than one package directory.",
        ["ZIP beklenmeyen, yinelenen veya boş bir dosya içeriyor."]="The ZIP contains an unexpected, duplicate, or empty file.",
        ["ZIP dosyası 100 MB sınırını aşıyor."]="A ZIP file exceeds the 100 MB limit.",
        ["ZIP açılmış boyutu 100 MB sınırını aşıyor."]="The extracted ZIP size exceeds the 100 MB limit.",
        ["ZIP gerekli kurulum dosyalarını içermiyor."]="The ZIP does not contain the required installation files.",
        ["Güncelleme klasörü bir dosya sistemi bağlantısı içeriyor."]="The update directory contains a file system link.",
        ["İçerik izin verilen boyutu aşıyor."]="The content exceeds the allowed size.",
        ["Bilinmiyor"]="Unknown", ["bilinmiyor"]="unknown", ["Bilinmiyor (availabilityUnknown)"]="Unknown (could not be compared)",
        ["Bilinmiyor (WUA bildirmiyor)"]="Unknown (not reported by WUA)",
