    };

    // Only recognize explicit app-generated templates. Never rewrite arbitrary OS logs.
    private static readonly (string Pattern,string Format)[] Templates =
    [
        (@"^(\d+) ciddi bulgu; (\d+) uyarı; (\d+) belirsiz kontrol\.$","{0} ciddi bulgu; {1} uyarı; {2} belirsiz kontrol."),
        (@"^(\d+) uyarı; (\d+) belirsiz kontrol\.$","{0} uyarı; {1} belirsiz kontrol."),
        (@"^(\d+) kontrolün sonucu bilinmiyor\.$","{0} kontrolün sonucu bilinmiyor."),
        (@"^Dikkat isteyen (\d+) bulgu var$","Dikkat isteyen {0} bulgu var"),
        (@"^Yeni sürüm hazır: ([0-9.]+)\. Paket kurulumdan önce doğrulanır\.$","Yeni sürüm hazır: {0}. Paket kurulumdan önce doğrulanır."),
        (@"^Defender (\d+) etkin tespit bildirdi\. Windows Güvenliği'ni inceleyin\.$","Defender {0} etkin tespit bildirdi. Windows Güvenliği'ni inceleyin."),
        (@"^Gelecek tarihli kayıt: (.+)$","Gelecek tarihli kayıt: {0}"),
        (@"^(.+) telemetri$","{0} telemetri"),
        (@"^(.+) hata sayacı$","{0} hata sayacı"),
        (@"^(.+) boş alan$","{0} boş alan"),
        (@"^WinGet görünür listesinde (\d+) yazılım güncellemesi bulundu\. Bu sınırlı liste tam envanter değildir; sabitlenmiş, eşleştirilemeyen veya diğer kaynaklardaki programların durumu bilinmiyor\.$","WinGet görünür listesinde {0} yazılım güncellemesi bulundu. Bu sınırlı liste tam envanter değildir; sabitlenmiş, eşleştirilemeyen veya diğer kaynaklardaki programların durumu bilinmiyor.")
    ];

    internal static string KnownText(string value)
    {
        if(!Language.StartsWith("en",StringComparison.OrdinalIgnoreCase) || string.IsNullOrEmpty(value))return value;
        foreach(var (pattern,format) in Templates)
        {
            var match=Regex.Match(value,pattern,RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100));
            if(match.Success)return F(format,match.Groups.Cast<Group>().Skip(1).Select(g=>(object)g.Value).ToArray());
        }
        string translated=T(value);
        if(translated!=value)return translated;
        foreach(var (prefix,format) in new[]{
            ("Sürüm bilgisi doğrulanamadı: ","Sürüm bilgisi doğrulanamadı: {0}"),
            ("Zamanlama durumu okunamadı: ","Zamanlama durumu okunamadı: {0}")})
            if(value.StartsWith(prefix,StringComparison.Ordinal))return F(format,KnownText(value[prefix.Length..]));
        foreach(var (prefix,label) in new[]{("Unknown: ","Doğrulanamadı:"),("Checked: ","Kontrol edildi:"),("Doğrulanamadı: ","Doğrulanamadı:"),("Kontrol edildi: ","Kontrol edildi:")})
            if(value.StartsWith(prefix,StringComparison.Ordinal))return T(label)+" "+KnownText(value[prefix.Length..]);
        // Antivirus summaries may be a known action sentence followed by a status sentence.
        foreach(var action in new[]{"Windows imza güncelleme komutu döndü. Güncel imza bilgisi işlem sonrasında tekrar okundu.",
            "İmzalar güncellendi ve istenen tarama komutu Windows Defender'a iletildi. Komutun dönmesi temiz sonuç veya taramanın tamamlandığı garantisi değildir; son zamanları ve Windows Güvenliği'ni inceleyin.",
            "Başka bir Sistem Pusulası antivirüs işlemi sürüyor. İkinci işlem başlatılmadı.",
            "İşlem başlatılmadı. Yalnızca sağlayıcıları doğrulanan ve Normal modda etkin Defender ile kullanılabilir. Başka veya bilinmeyen antivirüs sağlayıcısı varsa kendi uygulamasını kullanın.",
            "İmzalar güncellendi, ancak sağlayıcı veya Defender durumu değişti. Tarama başlatılmadı.",
            "İmzalar güncellendi; tarama komutu başarısız oldu. Windows Güvenliği'nden işlem durumunu kontrol edin.",
            "İşlem tamamlanamadı. İmza güncelleme başarısızsa tarama başlatılmaz. Yönetici izni veya Windows Güvenliği'ndeki durumu kontrol edin."})
            if(value.StartsWith(action+" ",StringComparison.Ordinal))return T(action)+" "+KnownText(value[(action.Length+1)..]);
        return value;
    }
}
